wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    /// DropSeen: keep only the items the 'seen' store has never recorded.
    ///
    /// The item's `id` is the parser-computed digest, safe as a store key; the
    /// node asks the read-only handle about that one key and drops the item if a
    /// value is present. There is no `put` in `state-read`, so this run cannot
    /// change what the next run sees — the read-only mode is the absence of the
    /// function, not a check here.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
